from pathlib import Path
import shutil,json,hashlib,re
lab=Path('F:/Projects/tyrax2-lab-20261001')
src=lab/'arena-check-night/game'
dst=lab/'night-isolation/game'
assert not dst.exists()
shutil.copytree(src,dst,ignore=shutil.ignore_patterns('obj','*.log','*.elf','*.elf.sym','*.p2s','ps2link.run'))
header='''#pragma once
namespace nightIsolation {
inline unsigned phase = 0;
inline bool group(unsigned n) { return phase == n; }
}
'''
(dst/'inc/night_isolation.hpp').write_bytes(header.encode())
def edit(rel,old,new):
 p=dst/rel; s=p.read_text(encoding='utf-8'); assert s.count(old)==1,(rel,old,s.count(old)); p.write_bytes(s.replace(old,new).encode('utf-8'))
def include(rel):
 p=dst/rel; s=p.read_text(encoding='utf-8'); p.write_bytes(('#include "night_isolation.hpp"\n'+s).encode('utf-8'))
for rel in ['src/terrain_game.cpp','src/gen/game_lighting.gen.cpp','src/gen/game_vehicles.gen.cpp','src/scripts/district_mood.cpp']:
 include(rel)
edit('src/terrain_game.cpp','void TerrainGame::loop() {','''void TerrainGame::loop() {
  static bool announced = false, done = false;
  if (!announced) {
    printf("NIGHTISOLATE phase=0 first=%lu\\n",(unsigned long)ftrig::frame); fflush(stdout);
    announced = true;
  }
  const unsigned desired = ftrig::frame / 2200;
  if (desired <= 6 && desired != nightIsolation::phase) {
    engine->renderer.core.synchronizeFrame();
    nightIsolation::phase = desired;
    printf("NIGHTISOLATE phase=%u first=%lu\\n",desired,(unsigned long)ftrig::frame); fflush(stdout);
    loadScene(currentScene);
  }
  if (desired > 6 && !done) {
    printf("NIGHTISOLATE done first=%lu\\n",(unsigned long)ftrig::frame); fflush(stdout);
    done = true;
  }
''')
edit('src/terrain_game.cpp','  updateDynLights(engine, scriptCtx);','''  updateDynLights(engine, scriptCtx);
  // Keep light-effect runtime levels, but remove only live per-bag lighting.
  if (nightIsolation::group(3)) engine->renderer.core.clearDynLights();''')
for name in ['updateAndRenderLightPools','renderProjShadows']:
 phase=2 if 'Pools' in name else 1
 edit('src/gen/game_lighting.gen.cpp','void TerrainGame::'+name+'() {','void TerrainGame::'+name+'() {\n  if (nightIsolation::group('+str(phase)+')) return;')
edit('src/gen/game_lighting.gen.cpp','const Vec4* viewAt, int portal) {','const Vec4* viewAt, int portal) {\n  if (nightIsolation::group(2)) return;')
edit('src/gen/game_vehicles.gen.cpp','if (v.lightsOn > 0 && !(v.lampBroken & 1) && flashGoboTex &&','if (!nightIsolation::group(5) && v.lightsOn > 0 && !(v.lampBroken & 1) && flashGoboTex &&')
edit('src/scripts/district_mood.cpp','ctx.objects[i].visible = night;','ctx.objects[i].visible = night && !nightIsolation::group(4);')
out={'phases':['full night before','no projected shadows','no scene light pools/beams','no live per-bag dynamic lighting (effect levels retained)','no night dressing','no vehicle headlight ground pools (lamp emission/glow retained)','full night restored'], 'frames_per_phase':2200,'warm_work_start_offset':1100,'work_sample_count':512,'period_summary_offsets':list(range(1100,1600,50)),'engine':str(lab/'arena-check-night/tyra'),'source_game':str(src),'artifacts':{str(p.relative_to(dst)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [dst/'inc/night_isolation.hpp',dst/'src/terrain_game.cpp',dst/'src/gen/game_lighting.gen.cpp',dst/'src/gen/game_vehicles.gen.cpp',dst/'src/scripts/district_mood.cpp']}}
(lab/'night-isolation/fixture.json').write_bytes((json.dumps(out,indent=2)+'\n').encode('utf-8'))
print(json.dumps(out['phases'],indent=2))
